"""Render the formal audit from replayed tables; no independent mutable totals."""
from __future__ import annotations

from scripts.week9_audit_diagnostics import mean


def table(headers, rows):
    def cell(value):
        return str(value).replace('|', '\\|').replace('\n', ' ')
    return ['| ' + ' | '.join(map(cell, headers)) + ' |', '| ' + ' | '.join('---' for _ in headers) + ' |'] + ['| ' + ' | '.join(map(cell, row)) + ' |' for row in rows]


def record(r):
    return f"{r['wins']}-{r['losses']}-{r['pushes']}"


def report(finals, grades, d, process, sequences, clv, custody):
    weekly = {(r['week'], r['market']): r for r in d['weekly']}
    lookup = {(r['market'], r['game_id']): r for r in grades}
    games = {r['game_id']: r for r in process['games']}
    lines = ['# Week 9 formal postgame audit — v1', '',
             'Formal score reconciliation and grading COMPLETE. Historical CLV INCOMPLETE. Owner approval PENDING. Merge recommendation HOLD until exact-tree CI and independent review are recorded. Master Prompt v2.8 and every sealed selection remain unchanged.', '',
             'This additive audit supersedes the authority of the preliminary On3 grading at commit `190c8949edcf8da806908b567d4daa59b605f1cd`; it does not overwrite those five files. All 54 scores agree across fresh ESPN summaries, the ESPN scoreboard and CFBD finals. All 108 independently computed grades, locked lines, cover margins and preliminary six-decimal forecast errors reconcile without discrepancies.', '',
             f"Custody verifies {custody['input_files_verified']} pinned input files, including all {custody['original_protected_files_verified']} previously recorded protected artifacts. The source SQLite database has integrity `ok`, zero foreign-key violations, and SHA-256 `{custody['source_database_sha256']}`. Retrieval times, raw/compressed hashes, game IDs, orientation and final flags are retained in capture manifests and the 54-row final-score table.", '',
             'ESPN and CFBD are separately retrieved providers, but may share upstream scoring data; agreement is corroboration rather than proof of independent statistical origins. The original optional `/games/advanced` request returned 404 and remains archived. A separate successful `/stats/game/advanced` capture supplies the diagnostic statistics ([provider endpoint documentation](https://github.com/CFBD/cfbd-python/blob/main/README.md)).', '',
             '## Full-card and cross-week results', '', d['units'], '', d['evidence_boundary'], '']
    lines += table(['Week', 'Market', 'N', 'W-L-P', 'Hit rate', 'MAE', 'RMSE', 'Bias actual−forecast', '-110 units', 'Locked-line MAE'],
                   [[r['week'], r['market'], r['n'], record(r), f"{r['hit_rate']:.2%}", f"{r['mae']:.3f}", f"{r['rmse']:.3f}", f"{r['bias_actual_minus_prediction']:+.3f}", f"{r['units_minus110']:+.3f}", f"{r['locked_line_baseline_mae']:.3f}"] for r in d['weekly']])
    w8, w9 = weekly['8', 'TOTAL'], weekly['9', 'TOTAL']
    lines += ['', '## Does the totals rebound establish an improvement?', '',
              f"Week 9 totals rose from {record(w8)} to {record(w9)}. MAE improved by {w8['mae']-w9['mae']:.3f} points and RMSE by {w8['rmse']-w9['rmse']:.3f}, while directional underprediction fell from {w8['bias_actual_minus_prediction']:.3f} to {w9['bias_actual_minus_prediction']:.3f}. These are actual descriptive improvements in forecast error, not merely a change in win count.", '',
              f"However, the 54-game hit-rate Wilson 95% interval is {w9['hit_rate_wilson95'][0]:.1%}–{w9['hit_rate_wilson95'][1]:.1%}, spanning both 50% and the 52.38% break-even rate at -110. The locked-total baseline beats the model by {w9['mae']-w9['locked_line_baseline_mae']:.3f} MAE points and {w9['rmse']-w9['locked_line_baseline_rmse']:.3f} RMSE points. The week is compatible with ordinary outcome variance and does not demonstrate a new calibrated edge or structural model improvement. Week-to-week matchup composition changed; repeated teams invalidate treating every comparison as an independent experiment.", '',
              '## Frozen selection cohorts', '', 'Ranks 1–5, 6–10 and 11+ are nonoverlapping within each market/week. Top 10 is the union of the first two segments and is never added again to a cumulative return. Human revisions, governed picks and research picks overlap; their returns must not be summed. Mixed ATS/totals cohort forecast-target metrics are deliberately not pooled.', '']
    lines += table(['Cohort', 'N', 'W-L-P', '-110 units'], [[r['cohort'], r['n'], record(r), f"{r['units_minus110']:+.3f}"] for r in d['frozen_cohorts']])
    lines += ['', '### Latest saved human five — recommendations, not owner-approved picks', '']
    latest = [('ATS','401858505',2),('ATS','401859185',2),('TOTAL','401871095',2),('TOTAL','401858278',1),('ATS','401869963',1)]
    lines += table(['Order', 'Matchup', 'Frozen selection / line', 'Frozen forecast', 'Human confidence', 'Final away–home', 'Result', 'Cover margin'],
                   [[i, f"{r['away']} @ {r['home']}", f"{r['selection']} {r['locked_line']}", r['raw_projection'], confidence,
                     f"{r['away_score']}–{r['home_score']}", r['result'], r['cover_margin']] for i, (market,gid,confidence) in enumerate(latest,1) for r in [lookup[market,gid]]])
    lines += ['', 'The October 28 morning and evening fives each went 3–2; the October 29 morning decision and October 30 retained version each went 4–1. These are four revisions of the same week, not 20 independent outcomes. Friday preserved already-started Thursday rows byte-for-byte through the existing owner-review verifier. The initial frozen ten is a candidate set with separate within-market ranks, not an invented combined ordering.', '',
              '### FAU–North Texas removal', '',
              'The recorded October 29 11:53:45 UTC decision replaced FAU–North Texas Under 77.5 (rank 5→6) with SMU–Syracuse Under 58.5 (rank 6→4), and moved Troy from 4→5. This preceded Thursday kickoff at 23:30 UTC. The unchanged original combined research board kept FAU Under at rank 1. The full pregame rationale, source capture timestamps and hashes are copied by reference and verbatim fields in `game_process_evidence.json`; postgame observations below are not presented as pregame knowledge.', '',
              'FAU Under lost while SMU Under won: the single substitution improved the recorded five by one win and 21/11 = 1.909091 hypothetical units. It supports this particular decision descriptively, not a causal claim that human review has a repeatable edge. Original combined research 3–2 versus latest human 4–1 has the same one-win difference but involves several substitutions and overlaps.', '',
              '## Ranking discrimination and confidence', '']
    lines += table(['Weeks','Market','Rank segment','N','W-L-P','-110 units'],
                   [[r['week'],r['market'],r['rank_segment'],r['n'],record(r),f"{r['units_minus110']:+.3f}"] for r in d['nonoverlapping_rank_segments']])
    lines += ['', 'Higher AUC means more wins at higher score/edge; 0.5 means no discrimination. Permutation p-values are exploratory, unadjusted for multiple comparisons or repeated-team clustering. No score is promoted to a validated probability.', '']
    lines += table(['Weeks','Market','Variable','N','Win correlation','AUC','Exploratory p'],
                   [[r['week'],r['market'],r['field'],r['n'],r['point_biserial_r'],r['auc_tie_half'],r['exploratory_permutation_p']] for r in d['predictive_discrimination']])
    lines += ['', 'Frozen confidence buckets (all ATS confidence values are 1; there is no Week 9 ATS confidence ladder to validate):', '']
    lines += table(['Weeks','Market','Confidence','N','W-L-P','Hit rate','MAE','-110 units'],
                   [[r['week'],r['market'],r['bucket'],r['n'],record(r),r['hit_rate'],r['mae'],r['units_minus110']] for r in d['segments'] if r['dimension']=='confidence' and r['week'] in ('9','5-9')])
    lines += ['', 'Brier score, log loss, mean uncalibrated score and actual hit rate by confidence and score bucket appear in `confidence_calibration.csv`. Confidence 1–5 is an ordinal archived label, not a percentage. Descriptive Brier/log loss of research scores does not confer probability calibration. Latest human confidence 2 went 2–1 (n=3), confidence 1 went 2–0 (n=2); neither supports a reliability ordering.', '']
    lines += table(['Market','N','Within archived 1σ','Within archived 2σ','Empirical |error| p90','p95'],
                   [[r['market'],r['n'],r['within_one_archived_sigma'],r['within_two_archived_sigma'],r['empirical_absolute_error_nearest_rank_p90'],r['empirical_absolute_error_nearest_rank_p95']] for r in d['uncertainty_coverage']])
    lines += ['', '## Extreme misses, pace and defensive performance', '',
              'All 54 matchups have captured team/player box scores, advanced offense/defense, drives and plays. The following measurements are postgame descriptions, not adjusted forecasts. Advanced offensive snap/drive counts include provider-specific rules and overtime; they measure volume, not clock-adjusted tempo. Explosives are pass gains ≥20 and rush gains ≥10 from explicitly classified plays. Return/ambiguous-fumble plays are excluded from that definition.', '']
    lines += table(['Market','Matchup','Frozen forecast','Actual target','Signed error','Frozen pick','Result'],
                   [[r['market'],f"{r['away']} @ {r['home']}",r['raw_projection'],r['actual_model_target'],r['forecast_error_actual_minus_predicted'],f"{r['selection']} {r['locked_line']}",r['result']] for market in ('ATS','TOTAL') for r in [r for r in d['extreme_errors'] if r['market']==market][:10]])
    selected_ids = list(dict.fromkeys(['401862812','401860908','401869963','401858505','401860910','401858502'] + [r['game_id'] for r in d['extreme_errors'] if r['market']=='TOTAL'][:5]))
    lines += ['', 'Selected process evidence (complete tables cover all 54):', '']
    lines += table(['Matchup','Total / frozen forecast','Offensive plays','Drives','Yards','Pass≥20 / rush≥10','Non-offensive points*','OT'],
                   [[f"{r['away']} @ {r['home']}",f"{r['actual_total']} / {float(r['frozen_projection']):.3f}",r['provider_advanced_offensive_plays'],r['provider_advanced_offensive_drives'],r['total_yards'],f"{r['explosive_pass_20_plus']} / {r['explosive_rush_10_plus']}",r['non_offensive_points_with_bundled_conversions'],r['overtime']] for gid in selected_ids for r in [games[gid]]])
    lines += ['', '*Non-offensive point deltas include any conversion bundled by ESPN with a return touchdown. They are not a counterfactual subtraction from the actual final.', '',
              'FAU–UNT: 89 actual versus 59.785 frozen, an underforecast of 29.215 points. There were 172 offensive plays, 26 provider drives, 1,167 yards, 13 explosive passes and 10 explosive rushes. No non-offensive scoring event occurred. The failure therefore cannot be attributed to a special-teams touchdown or a defensive return; high volume and successful explosive offense are directly observed. The 17.715-point line gap was never evidence of 85.49% validated win probability.', '',
              'Texas State–Boise State: 91 actual versus 55.744 frozen, a 35.256-point miss, with 152 plays, 27 drives and 913 yards. One non-offensive scoring event contributed 7 bundled points. Even 84 remaining arithmetic points exceed the frozen forecast by 28.256; that arithmetic does not model how the game would have unfolded without the return. The recurring Texas State total miss warrants testing explicit possessions and explosive-play features using pregame-only data, not adding a hindsight adjustment.', '',
              'Troy–JMU went to overtime; final totals and ATS grades include overtime under ordinary contest grading. No medical or causal QB valuation is inferred from a box score. Observed passers, passing PPA, success rate, defensive PPA allowed and possession-time strings are preserved in the team/player tables. Pregame QB/OL/defense uncertainties remain the statements actually archived before kickoff; postgame participation cannot retroactively certify pregame availability.', '']
    lines += table(['Postgame subgroup','N','W-L-P','MAE','Bias','-110 units'],
                   [[r['segment'],r['n'],record(r),r['mae'],r['bias_actual_minus_prediction'],r['units_minus110']] for r in process['exploratory_process_segments']])
    lines += ['', 'These cutoffs (150 plays, 26 drives) were chosen for this postgame exploration. A valid future pace feature must predict volume before kickoff; conditioning on realized volume is explanatory only.', '',
              '## Hooks, scoring sequences and CLV', '',
              f"All {sum(r['sequence_status']=='VALIDATED' for r in sequences)} ATS scoring sequences passed identity, clock, monotonic-score and final-score reconciliation. No selected ATS win meets the explicit backdoor-cover definition: selected-team scoring in the final five minutes or overtime changes non-cover to final cover while the team loses outright. Other late-score classifications are preserved in `scoring_sequence_review.json`. A hook is classified only at a half-point boundary with a validated sequence.", '']
    lines += table(['Market','Matchup','Pick / line','Cover margin','Hook'],
                   [[r['market'],f"{r['away']} @ {r['home']}",f"{r['selection']} {r['locked_line']}",r['cover_margin'],r['hook_classification']] for r in grades if r['hook_classification'] not in ('NOT_APPLICABLE','UNVERIFIABLE')])
    lines += ['', f"CLV remains INCOMPLETE for all 108 selections: {clv['timestamped_pregame_observations']} archived pregame market observations, zero qualified closing quotes. Receipt timestamps establish retrieval before kickoff, not freshness or the final bookmaker closing price. No postgame odds label is substituted. Key-number crossing and CLV-positive/negative stratification remain unavailable; irrecoverable closes do not by themselves block unrelated integrity repairs.", '',
              '## Quantified lessons and candidate changes — RESEARCH ONLY', '',
              '1. **Forecast calibration before ranking promotion.** Across 279 games per market, ATS MAE 12.615 versus locked-line 11.858 and totals MAE 13.317 versus 12.690. Cumulative returns are negative after vig in both markets. Candidate A adds half of the strictly prior-week mean signed error; Candidate B blends the forecast 50/50 with the original locked-line implied target. Their temporally ordered replay is below. These fixed proposals were chosen retrospectively and require a new prospective holdout; no selection or forecast is replaced.', '',
              '2. **Uncertainty and confidence.** Use the archived interval-coverage counts and per-bucket sample sizes, not raw point gap, to assess reliability. Research proposal: test a prior-only residual RMSE floor, and require at least 100 out-of-sample observations per proposed confidence bucket before a promotion decision. Compare coverage at 68%/95%, Brier/log loss and Top 5 returns. The sample-size rule is a proposed governance threshold, not adopted policy.', '',
              '3. **Totals volume and efficiency.** Research a possession-count model multiplied by separately estimated points per possession, with lagged explosive-pass/rush rates and uncertain QB participation as explicit scenario inputs. Require at least 200 held-out game predictions and compare MAE/RMSE with both v2.8 and the original locked total. Numeric acceptance proposal: ≥0.5-point MAE improvement with no RMSE increase, plus no deterioration in interval coverage; reject if confidence intervals include material degradation. The 54 Week 9 process observations are exploratory support, not training/validation proof.', '',
              '4. **Ranking.** Do not pool capped ATS research scores with a different totals score scale. Test separate prior-only calibration with walk-forward predictions; assess AUC, Brier/log loss, 1–5 versus 6–10 versus 11+ and same-game ATS/totals correlation. Propose at least 40 future Top 5 picks per market before evaluating ranking uplift, with a predeclared paired uncertainty interval. No ATS/totals diversification quota is introduced.', '',
              '5. **Human review.** The latest five improved one result via the documented FAU→SMU substitution, but n=1 replacement and n=5 final selections are insufficient to infer skill. Continue preserving every review and compare only pre-kickoff decisions against the same frozen candidates. Never count multiple revisions of one game as independent bets.', '',
              'Proposed acceptance criteria must be frozen before future outcomes, evaluated in rolling chronological folds, and reported whether accepted or rejected. Any adoption requires the completed qualifying governance audit, explicit owner approval and a new version identifier; this PR adopts none.', '']
    lines += table(['Candidate','Market','Test week','Train N','Test N','Original MAE','Candidate MAE','Original RMSE','Candidate RMSE'],
                   [[r['candidate'],r['market'],r['evaluation_week'],r['train_n'],r['test_n'],r['baseline_mae'],r['candidate_mae'],r['baseline_rmse'],r['candidate_rmse']] for r in d['walk_forward_candidates']])
    lines += ['', '## Reproduction, limitations and governance', '',
              'Run `python -m scripts.build_week9_formal_audit --verify` for exact offline byte replay, `python -m scripts.verify_replay_compat` for the repaired Week 7/8/9 dependency gates, and `python -m pytest -q` for the full suite. The writer refuses any existing output directory. The verifier requires exact output inventory, source-code identity and a separately pinned input inventory. It never rewrites evidence. Exact command execution, tested source/merge SHAs, native Windows results and GitHub matrix results are recorded separately in the delivery verification documents so this deterministic report does not invent test provenance.', '',
              'The formal implementation descends from PR #47 (`0d9a4b56bd49e3fbef4326aa7a5bd6eec9d13e29`) and preserves the repaired dependency chain. PR #48 remains draft until independent review. COMMENTED is not APPROVED; the author cannot substitute for an independent reviewer. No reviewer has been designated.', '',
              'Known limits: missing qualified historical closes; provider upstream dependence; small/confounded subgroups and repeated teams; no causal injury valuation or validated human-confidence probabilities; realized process data cannot be used for pregame ranking; Weeks 5–6 research order is retrospective; original mixed research ranking is not a production-valid score comparison. No raw artifact, schema, database, v2.8 policy, locked line, model output or owner approval changes.', '',
              'Rollback: abandon/revert only this additive audit implementation and new audit/evidence files; retain the captured evidence and all prior versions for custody. No migration or database recovery is required. Unrelated main-worktree changes are excluded.', '']
    return '\n'.join(lines)
